--
-- Table structure for table `t_video_info`
--

DROP TABLE IF EXISTS `t_video_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_video_info` (
  `video_id` int NOT NULL AUTO_INCREMENT,
  `video_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `original_title` varchar(255) DEFAULT NULL COMMENT '原始标题',
  `overview` text COMMENT '简介',
  `tagline` varchar(500) DEFAULT NULL COMMENT '标语',
  `budget` bigint DEFAULT '0' COMMENT '预算',
  `revenue` bigint DEFAULT '0' COMMENT '票房',
  `popularity` double DEFAULT '0' COMMENT '热度值',
  `vote_average` double DEFAULT '0' COMMENT '平均评分',
  `vote_count` int DEFAULT '0' COMMENT '评分人数',
  `runtime` int DEFAULT '0' COMMENT '片长(分钟)',
  `release_date` date DEFAULT NULL COMMENT '上映日期',
  `original_language` varchar(10) DEFAULT NULL COMMENT '原始语言',
  `studios` varchar(500) DEFAULT NULL COMMENT '制作公司',
  `country` varchar(20) DEFAULT 'JP' COMMENT '国家/地区',
  `source` varchar(30) DEFAULT NULL COMMENT '原作来源',
  `premiered` varchar(30) DEFAULT NULL COMMENT '首播季度',
  `video_type` varchar(20) DEFAULT NULL COMMENT '动画类型',
  `poster_path` varchar(500) DEFAULT NULL COMMENT '海报路径',
  `heat_score` double DEFAULT '0' COMMENT '综合热度评分',
  `video_category` tinyint(1) DEFAULT NULL COMMENT '动漫元数据',
  `create_time` date DEFAULT NULL,
  `creator_id` int DEFAULT NULL COMMENT '动漫记录占位',
  `last_modify_time` datetime DEFAULT NULL,
  `video_url` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '海报/封面地址',
  PRIMARY KEY (`video_id`) USING BTREE,
  KEY `idx_video_name` (`video_name`(50)),
  KEY `idx_heat_score` (`heat_score`)
) ENGINE=InnoDB AUTO_INCREMENT=55736 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

